def duplicateNumbersXOR(nums):
    # Count occurrences of each number
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    xor_result = 0
    # XOR all numbers that appear exactly twice
    for num, freq in count.items():
        if freq == 2:
            xor_result ^= num

    return xor_result
